--

-- Name: assert_safe_group_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_safe_group_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    v_privileged boolean;
BEGIN
    SELECT rolbypassrls OR rolsuper INTO v_privileged
    FROM pg_catalog.pg_roles
    WHERE rolname = current_user;

    IF COALESCE(v_privileged, false) THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.group_shards := 0;
        NEW.size_tier := 'micro'::public.size_tier;
        NEW.frozen_at := NULL;
        NEW.rank_bracket := 'b0_20'::public.rank_bracket;
        RETURN NEW;
    END IF;

    IF NEW.group_shards = OLD.group_shards
        AND NEW.size_tier = OLD.size_tier
        AND NEW.frozen_at IS NOT DISTINCT FROM OLD.frozen_at
        AND NEW.rank_bracket = OLD.rank_bracket
    THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'groups server-managed columns (group_shards, size_tier, frozen_at, rank_bracket) may only be changed by a privileged role';
END;
$$;


--

-- Name: increment_group_shards(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_group_shards() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.groups SET group_shards = group_shards + NEW.shards_contributed
    WHERE id = NEW.group_id;
    RETURN NEW;
END;
$$;


--

-- Name: is_group_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_group_member(p_group_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.group_members
        WHERE group_id = p_group_id
          AND user_id = auth.uid()
          AND status = 'active'
    );
$$;


--

-- Name: promote_next_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_next_member(p_group_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_next uuid;
BEGIN
    -- Prefer a co-promotor; fall back to a random ACTIVE member. Invited
    -- members (status <> 'active') never receive leadership.
    SELECT user_id INTO v_next
    FROM public.group_members
    WHERE group_id = p_group_id AND status = 'active' AND role = 'co_promotor'
    ORDER BY random()
    LIMIT 1;

    IF v_next IS NULL THEN
        SELECT user_id INTO v_next
        FROM public.group_members
        WHERE group_id = p_group_id AND status = 'active' AND role = 'member'
        ORDER BY random()
        LIMIT 1;
    END IF;

    IF v_next IS NOT NULL THEN
        UPDATE public.group_members SET role = 'promotor'
        WHERE group_id = p_group_id AND user_id = v_next;
    END IF;
END;
$$;


--

-- Name: reassign_group_promotor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reassign_group_promotor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    gid uuid;
BEGIN
    -- Promotor membership row deleted (kick is RLS-blocked for everyone but
    -- the promotor itself, so this is: promotor leaves, hard-delete cron,
    -- or account-delete cascade) → pass leadership on. Note: plpgsql does
    -- NOT short-circuit AND/OR conditions, so the OLD.role access must live
    -- in a DELETE-only branch (this function also fires on users UPDATE).
    IF TG_OP = 'DELETE' THEN
        IF OLD.role = 'promotor' THEN
            PERFORM public.promote_next_member(OLD.group_id);
        END IF;
        RETURN OLD;
    END IF;

    -- Promotor banned or soft-deleted → demote to member + pass leadership.
    -- (Fires only on banned_at/deleted_at column updates; the demotion
    -- below is a group_members UPDATE, so there is no recursion.)
    IF TG_OP = 'UPDATE' THEN
        IF (NEW.banned_at IS NOT NULL AND OLD.banned_at IS NULL)
           OR (NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL) THEN
            FOR gid IN
                SELECT group_id FROM public.group_members
                WHERE user_id = NEW.id AND role = 'promotor'
            LOOP
                UPDATE public.group_members SET role = 'member'
                WHERE group_id = gid AND user_id = NEW.id AND role = 'promotor';
                PERFORM public.promote_next_member(gid);
            END LOOP;
        END IF;
        RETURN NEW;
    END IF;

    RETURN COALESCE(OLD, NEW);
END;
$$;


--

-- Name: transfer_promotor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_promotor(p_group_id uuid, p_new_promotor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor_role public.group_role;
    v_new_role   public.group_role;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'not_authenticated';
    END IF;

    SELECT role INTO v_actor_role
    FROM public.group_members
    WHERE group_id = p_group_id AND user_id = auth.uid() AND status = 'active';

    IF v_actor_role IS NULL THEN
        RAISE EXCEPTION 'not_a_member';
    END IF;
    IF v_actor_role <> 'promotor' THEN
        RAISE EXCEPTION 'not_promotor';
    END IF;

    SELECT role INTO v_new_role
    FROM public.group_members
    WHERE group_id = p_group_id AND user_id = p_new_promotor_id AND status = 'active';

    IF v_new_role IS NULL THEN
        RAISE EXCEPTION 'new_member_not_found';
    END IF;

    -- Single transaction: demote self, promote the successor. Idempotent —
    -- a successor who is already promotor leaves exactly one promotor.
    UPDATE public.group_members SET role = 'co_promotor'
    WHERE group_id = p_group_id AND user_id = auth.uid() AND role = 'promotor';

    UPDATE public.group_members SET role = 'promotor'
    WHERE group_id = p_group_id AND user_id = p_new_promotor_id;

    RETURN jsonb_build_object('status', 'ok');
END;
$$;


--

-- Name: update_group_size_tier(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_group_size_tier() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    member_count integer;
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT COUNT(*) INTO member_count FROM public.group_members WHERE group_id = NEW.group_id;
    ELSE
        SELECT COUNT(*) INTO member_count FROM public.group_members WHERE group_id = OLD.group_id;
    END IF;

    UPDATE public.groups SET size_tier = CASE
        WHEN member_count >= 257 THEN 'large'::public.size_tier
        WHEN member_count >= 51  THEN 'medium'::public.size_tier
        WHEN member_count >= 15  THEN 'small'::public.size_tier
        ELSE 'micro'::public.size_tier
    END WHERE id = COALESCE(NEW.group_id, OLD.group_id);

    RETURN COALESCE(NEW, OLD);
END;
$$;


